"""The Pi vectors: what the pinned pi-tui package's own functions return (test/parity/sdk-vectors/pi-tui/<export>.json, generated by
automation/gen/generate-sdk-vectors.mjs). Every case of every file is run."""

from __future__ import annotations

import json
import math
from pathlib import Path

import pytest

from pig_sdk import tui

VECTORS = Path(__file__).resolve().parents[3] / "test" / "parity" / "sdk-vectors" / "pi-tui"


def _undefined(v):
    return isinstance(v, dict) and v.get("$") == "undefined"


def _color(o):
    if o["kind"] == "indexed":
        return tui.IndexedColor(int(o["index"]))
    if o["kind"] == "rgb":
        return tui.RgbColorValue(o["r"], o["g"], o["b"])
    return tui.OklchColorValue(o["l"], o["c"], o["h"])


def _color_json(c):
    if c.kind == "indexed":
        return {"kind": "indexed", "index": float(c.index)}
    if c.kind == "rgb":
        return {"kind": "rgb", "r": float(c.r), "g": float(c.g), "b": float(c.b)}
    return {"kind": "oklch", "l": c.l, "c": c.c, "h": c.h}


_ATTRS = ("bold", "dim", "italic", "underline", "inverse", "strikethrough")


def _style(a):
    o = a[1]
    return tui.style_text(a[0], tui.TextStyle(**{k: o.get(k, False) for k in _ATTRS}, fg=_color(o["fg"]) if "fg" in o else None, bg=_color(o["bg"]) if "bg" in o else None), a[2])


def _opt(v):
    return {"$": "undefined"} if v is None else v


RUN = {
    "visibleWidth": lambda a: tui.visible_width(a[0]),
    "stripTerminalSequences": lambda a: tui.strip_terminal_sequences(a[0]),
    "truncateToWidth": lambda a: tui.truncate_to_width(*a),
    "wrapTextWithAnsi": lambda a: tui.wrap_text_with_ansi(*a),
    "sliceByColumn": lambda a: tui.slice_by_column(*a),
    "getOsc8LinkAtColumn": lambda a: _opt(tui.get_osc8_link_at_column(*a)),
    "fuzzyMatch": lambda a: {"matches": (m := tui.fuzzy_match(*a)).matches, "score": m.score},
    "fuzzyFilter": lambda a: tui.fuzzy_filter(a[0], a[1], lambda s: s),
    "parseKey": lambda a: _opt(tui.parse_key(a[0])),
    "isKeyRelease": lambda a: tui.is_key_release(a[0]),
    "isKeyRepeat": lambda a: tui.is_key_repeat(a[0]),
    "decodeKittyPrintable": lambda a: _opt(tui.decode_kitty_printable(a[0])),
    "matchesKey": lambda a: tui.matches_key(*a),
    "hyperlink": lambda a: tui.hyperlink(*a),
    "CURSOR_MARKER": lambda a: tui.CURSOR_MARKER,
    "parseColor": lambda a: _color_json(tui.parse_color(a[0])),
    "rgbColor": lambda a: _color_json(tui.rgb_color(*a)),
    "oklchColor": lambda a: _color_json(tui.oklch_color(*a)),
    "okhslColor": lambda a: _color_json(tui.okhsl_color(*a)),
    "indexedColor": lambda a: _color_json(tui.indexed_color(a[0])),
    "colorToRgb": lambda a: {"r": (r := tui.color_to_rgb(_color(a[0]))).r, "g": r.g, "b": r.b},
    "colorToHex": lambda a: tui.color_to_hex(_color(a[0])),
    "colorToOklch": lambda a: {"l": (o := tui.color_to_oklch(_color(a[0]))).l, "c": o.c, "h": o.h},
    "colorToOkhsl": lambda a: {"h": (o := tui.color_to_okhsl(_color(a[0]))).h, "s": o.s, "l": o.l},
    "foregroundAnsi": lambda a: tui.foreground_ansi(_color(a[0]), a[1]),
    "backgroundAnsi": lambda a: tui.background_ansi(_color(a[0]), a[1]),
    "mixColors": lambda a: _color_json(tui.mix_colors(_color(a[0]), _color(a[1]), a[2], a[3] or "oklch")),
    "styleText": _style,
    "styleTextWithAnsi": lambda a: tui.style_text_with_ansi(a[0], a[1], a[2], tui.TextAttributes(**{k: a[3].get(k, False) for k in _ATTRS})),
}


def _near(got, want):
    if isinstance(want, (int, float)) and not isinstance(want, bool):
        return isinstance(got, (int, float)) and (got == want or abs(got - want) <= 1e-9 * max(1, abs(want)))
    if isinstance(want, dict):
        if not isinstance(got, dict) or set(got) != set(want):
            return False
        neutral = any(isinstance(want.get(k), (int, float)) and want[k] < 1e-9 for k in ("c", "s"))
        return all(_near(got[k], x) for k, x in want.items() if not (k == "h" and neutral))
    if isinstance(want, list):
        return isinstance(got, list) and len(got) == len(want) and all(_near(g, w) for g, w in zip(got, want))
    return got == want


@pytest.mark.parametrize("export", sorted(RUN))
def test_pi_vectors(export):
    cases = json.loads((VECTORS / f"{export}.json").read_text(encoding="utf-8"))["cases"]
    assert cases
    for case in cases:
        args = case["args"]
        try:
            got = RUN[export](args)
            error = None
        except ValueError as e:
            got, error = None, str(e)
        if "throws" in case:
            assert error == case["throws"], (export, case["name"], args)
        else:
            assert error is None and (_near(got, case["result"]) or (_undefined(case["result"]) and _undefined(got))), (export, case["name"], args, got, case["result"])
